export const SEO_CLUSTERS = Array.from(new Set(CURATED_SEO_KEYWORDS.map(k => k.cluster)));

export const SEO_INTENTS = Array.from(new Set(CURATED_SEO_KEYWORDS.map(k => k.intent)));

export function searchCuratedKeywords(query: string, limit: number = 25): SeoKeywordItem[] {
  if (!query || !query.trim()) return CURATED_SEO_KEYWORDS.slice(0, limit);
  const q = query.toLowerCase().trim();
  const tokens = q.split(/\s+/);
  return CURATED_SEO_KEYWORDS.filter(item => {
    const kw = item.keyword.toLowerCase();
    const cat = item.category.toLowerCase();
    const cl = item.cluster.toLowerCase();
    return tokens.every(tok => kw.includes(tok) || cat.includes(tok) || cl.includes(tok));
  }).slice(0, limit);
}

export function generateHighCtrMeta(item: SeoKeywordItem): {
  title: string;
  description: string;
  canonical: string;
} {
  const kwCapitalized = item.keyword
    .split(' ')
    .map(w => w.charAt(0).toUpperCase() + w.slice(1))
    .join(' ');
  
  let actionSuffix = '2026: Official Portal, Download PDF & Direct Links';
  if (item.intent === 'Result / Cutoff') {
    actionSuffix = '2026 OUT: Scorecard Link, Cut Off Marks & Merit List';
  } else if (item.intent === 'Admit Card / Exam') {
    actionSuffix = '2026 Admit Card Released: Download Hall Ticket & Exam City';
  } else if (item.intent === 'Answer Key') {
    actionSuffix = '2026 Answer Key & Response Sheet: Direct Link & Objection';
  } else if (item.intent === 'Syllabus / PYQ') {
    actionSuffix = '2026 Syllabus & Exam Pattern PDF in Hindi/English Download';
  } else if (item.intent === 'Application / Form') {
    actionSuffix = '2026 Online Form: Apply Online, Last Date & Eligibility';
  }

  const title = `${kwCapitalized} - Sarkari Result ${actionSuffix}`;
  const description = `Access verified updates for ${kwCapitalized} on Sarkari Result Official Portal. Check notification dates, eligibility, vacancy, exam pattern, answer key, and direct application links.`;
  const canonical = `https://sarkariresultme.com${item.targetSlug}`;

  return { title, description, canonical };
}

